-- 0003_storage.sql : buckets et policies de stockage

insert into storage.buckets (id, name, public) values ('bank-statements', 'bank-statements', false) on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('budget-receipts', 'budget-receipts', false) on conflict (id) do nothing;
insert into storage.buckets (id, name, public) values ('course-documents', 'course-documents', true) on conflict (id) do nothing;
