insert into storage.buckets (id, name, public) values ('trainer-signatures', 'trainer-signatures', true) on conflict (id) do nothing;

create policy "Allow all for authenticated" on storage.objects for all to authenticated using ((bucket_id = 'email-attachments'::text)) with check ((bucket_id = 'email-attachments'::text));
